quantities.raw:
{
  "relationship": {
    "statement": "A decision tree classifies data by recursively splitting samples at feature thresholds that maximize purity gain (reduction in Gini impurity), then routing new inputs down matching branches to a leaf's majority class.",
    "formula": "G = 1 - \\sum_{k} p_k^2,\\quad \\Delta G = G_{\\text{parent}} - \\left(\\frac{n_L}{n}G_L + \\frac{n_R}{n}G_R\\right)",
    "assumptions": [
      "Binary classification with two equally sized classes (N = 20 samples total) along one primary feature X.",
      "Gini impurity measures node mixedness from 0 (pure single class) to 0.5 (50/50 split).",
      "A single decision stump splits at threshold t; deeper trees repeat this rule on each child node."
    ]
  },
  "quantities": [
    {
      "id": "threshold",
      "label": "Split threshold t",
      "unit": "",
      "role": "control",
      "meaning": "Cutoff value on feature X sending samples left (X <= t) or right (X > t)."
    },
    {
      "id": "separation",
      "label": "Class separation",
      "unit": "",
      "role": "control",
      "meaning": "Distance between Class A and Class B feature centers; lower values increase overlap."
    },
    {
      "id": "query_x",
      "label": "Test sample X",
      "unit": "",
      "role": "control",
      "meaning": "Feature value of a new point routed through the decision node to a leaf prediction."
    },
    {
      "id": "total_samples",
      "label": "Total samples N",
      "unit": "pts",
      "role": "fixed",
      "meaning": "Fixed number of labeled training points split across the root node."
    },
    {
      "id": "gini_parent",
      "label": "Parent Gini",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of the unsplit root node (0 is pure, 0.5 is maximally mixed)."
    },
    {
      "id": "gini_left",
      "label": "Left leaf Gini",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of samples with X <= t routed to the left child node."
    },
    {
      "id": "gini_right",
      "label": "Right leaf Gini",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of samples with X > t routed to the right child node."
    },
    {
      "id": "weighted_gini",
      "label": "Weighted child Gini",
      "unit": "",
      "role": "result",
      "meaning": "Sample-weighted average impurity of the left and right child nodes after splitting."
    },
    {
      "id": "gini_gain",
      "label": "Impurity gain",
      "unit": "",
      "role": "result",
      "meaning": "Reduction in Gini impurity achieved by splitting at threshold t; higher is better."
    },
    {
      "id": "leaf_confidence",
      "label": "Leaf confidence",
      "unit": "%",
      "role": "result",
      "meaning": "Majority-class percentage in the leaf reached by the test sample X."
    }
  ]
}

